/* ========================= CHAT: HELPERS / WEBHOOK ======================== */

// 🔌 Plak hier je eigen n8n webhook-URL (productie of test):
const WEBHOOK_URL = "PLAK_HIER_MIJN_N8N_WEBHOOK_URL";

// intake-antwoordsleutels → Supabase kolomnamen
const ANSWER_KEY_MAP = {
  aanvraagType: "aanvraag_type",
  aantalRuimtes: "aantal_ruimtes",
  woningType: "woning_type",
  planning: "planning",
  buitenunitLocatie: "buitenunit_locatie",
  eigendom: "eigendom",
  bestaandeAirco: "bestaande_airco",
};

function computeResult(answers, uploads) {
  const allPhotos = UPLOAD_SLOTS.every((s) => !!uploads[s.key]);
  const hasUnknown = Object.values(answers).some((a) => a && a.waarde === "onbekend");
  let scenario;
  if (allPhotos && !hasUnknown) scenario = 1;
  else if (!allPhotos && !hasUnknown) scenario = 2;
  else if (allPhotos && hasUnknown) scenario = 3;
  else scenario = 4;
  return { scenario, allPhotos, hasUnknown, ...SCENARIOS[scenario] };
}

function buildIntakePayload(answers, uploads, result, details) {
  const naam = `${(details.voornaam || "").trim()} ${(details.achternaam || "").trim()}`.trim();
  const waarde = (k) => (answers[k]?.waarde ?? null);
  return {
    formulier: `Offerteaanvraag — ${BRAND.name}`,
    versie: "1.3",
    ingediendOp: new Date().toISOString(),

    // Klantgegevens
    naam,
    telefoon: (details.telefoon || "").trim(),
    email: (details.email || "").trim(),
    postcode: (details.postcode || "").trim().toUpperCase(),
    plaats: (details.plaats || "").trim(),
    adres: (details.straat || "").trim(),
    toestemming_contact: !!details.toestemming,

    // Intake-antwoorden (Supabase-kolommen)
    aanvraag_type: waarde("aanvraagType"),
    aantal_ruimtes: waarde("aantalRuimtes"),
    woning_type: waarde("woningType"),
    planning: waarde("planning"),
    buitenunit_locatie: waarde("buitenunitLocatie"),
    eigendom: waarde("eigendom"),
    bestaande_airco: waarde("bestaandeAirco"),

    // Status & volledigheid
    ontbrekende_fotos: UPLOAD_SLOTS.filter((s) => !uploads[s.key]).map((s) => s.key),
    onbekende_antwoorden: Object.entries(answers)
      .filter(([, a]) => a.waarde === "onbekend")
      .map(([k]) => ANSWER_KEY_MAP[k] || k),
    status: result.scenario === 1 ? "compleet" : "in_beoordeling",
    volledigheid_score: result.score,

    // Extra context (leesbare keuzes) — niet-destructief
    antwoorden_leesbaar: Object.fromEntries(
      Object.entries(answers).map(([k, a]) => [ANSWER_KEY_MAP[k] || k, a.keuze])
    ),
    meta: { taal: "nl", bron: "website", userAgent: typeof navigator !== "undefined" ? navigator.userAgent : "" },
  };
}

// Customer-details step. Required to finish: naam, telefoon, email, postcode, plaats (+ consent).
const DETAIL_FIELDS = [
  { key: "voornaam", label: "Voornaam", type: "text", req: true, half: true, autoComplete: "given-name" },
  { key: "achternaam", label: "Achternaam", type: "text", req: true, half: true, autoComplete: "family-name" },
  { key: "telefoon", label: "Telefoonnummer", type: "tel", req: true, half: true, autoComplete: "tel", placeholder: "06 12345678" },
  { key: "email", label: "E-mailadres", type: "email", req: true, half: true, autoComplete: "email", placeholder: "naam@email.nl" },
  { key: "postcode", label: "Postcode", type: "text", req: true, half: true, autoComplete: "postal-code", placeholder: "1234 AB" },
  { key: "plaats", label: "Plaats", type: "text", req: true, half: true, autoComplete: "address-level2" },
  { key: "straat", label: "Straat + huisnummer", type: "text", req: false, half: false, autoComplete: "street-address", optional: true },
];

function validateDetails(d) {
  const has = (k) => (d[k] || "").trim().length > 0;
  const emailOk = /^\S+@\S+\.\S+$/.test((d.email || "").trim());
  const telOk = ((d.telefoon || "").replace(/\D/g, "").length >= 8);
  return {
    voornaam: has("voornaam"),
    achternaam: has("achternaam"),
    telefoon: telOk,
    email: emailOk,
    postcode: has("postcode"),
    plaats: has("plaats"),
    toestemming: !!d.toestemming,
  };
}
function detailsComplete(d) {
  const v = validateDetails(d);
  return v.voornaam && v.achternaam && v.telefoon && v.email && v.postcode && v.plaats && v.toestemming;
}

// Verstuurt de aanvraag als multipart/form-data (JSON payload + echte foto-bestanden).
// Belangrijk: GEEN Content-Type header zetten — de browser stelt zelf de multipart-boundary in.
async function sendIntake(payload, uploads) {
  const formData = new FormData();
  formData.append("payload", JSON.stringify(payload));

  if (uploads.binnenruimte?.file) formData.append("foto_binnenruimte", uploads.binnenruimte.file);
  if (uploads.buitenmuur?.file) formData.append("foto_buitenmuur", uploads.buitenmuur.file);
  if (uploads.meterkast?.file) formData.append("foto_meterkast", uploads.meterkast.file);

  const res = await fetch(WEBHOOK_URL, {
    method: "POST",
    body: formData,
  });
  if (!res.ok) throw new Error(`Webhook antwoordde met status ${res.status}`);
  return res;
}

/* ============================ CHAT: LOGIC (hook) ========================== */
/* Phases: intro → asking → upload → details → processing → done  (of: error) */
function useIntakeChat() {
  const [phase, setPhase] = useState("intro");
  const [stepIndex, setStepIndex] = useState(0);
  const [answers, setAnswers] = useState({});
  const [uploads, setUploads] = useState({});
  const [messages, setMessages] = useState([{ id: 0, from: "tom", text: OPENING_MESSAGE }]);
  const [isTyping, setIsTyping] = useState(false);
  const [result, setResult] = useState(null);
  const [details, setDetails] = useState({});
  const [error, setError] = useState(null);

  const idRef = useRef(1);
  const timers = useRef([]);
  const nextId = () => idRef.current++;
  useEffect(() => () => timers.current.forEach(clearTimeout), []);

  const push = (from, text) => setMessages((m) => [...m, { id: nextId(), from, text }]);

  const tomSays = useCallback((text, delay = 850) => {
    setIsTyping(true);
    const t = setTimeout(() => { setIsTyping(false); push("tom", text); }, delay);
    timers.current.push(t);
  }, []);

  const start = useCallback(() => {
    push("user", "Ja, graag 👍");
    setPhase("asking"); setStepIndex(0);
    const q = INTAKE_QUESTIONS[0];
    tomSays(`${q.lead}\n\n${q.question}`);
  }, [tomSays]);

  const answer = useCallback((option) => {
    const q = INTAKE_QUESTIONS[stepIndex];
    setAnswers((a) => ({ ...a, [q.key]: { vraag: q.question, keuze: option.label, waarde: option.value } }));
    push("user", option.label);
    const next = stepIndex + 1;
    if (next < INTAKE_QUESTIONS.length) {
      setStepIndex(next);
      const nq = INTAKE_QUESTIONS[next];
      tomSays(`${nq.lead}\n\n${nq.question}`);
    } else {
      setPhase("upload");
      tomSays("Fijn, dat was 'm.\n\nTot slot helpt u onze installateur enorm met een paar foto's. Voeg toe wat u bij de hand heeft.");
    }
  }, [stepIndex, tomSays]);

  const setUpload = useCallback((key, file) => {
    setUploads((u) => ({
      ...u,
      [key]: file
        ? { file, name: file.name, size: file.size, type: file.type, url: URL.createObjectURL(file) }
        : undefined,
    }));
  }, []);

  // From the photo step → go to the customer-details step.
  const finishPhotos = useCallback(() => {
    const count = Object.values(uploads).filter(Boolean).length;
    push("user", count > 0 ? `${count} foto${count > 1 ? "'s" : ""} toegevoegd ✅` : "Verder zonder foto's");
    setPhase("details");
    tomSays("Bijna klaar! Laat hieronder uw contactgegevens achter, dan neemt onze installateur contact met u op over de offerte.");
  }, [uploads, tomSays]);

  const setDetail = useCallback((key, value) => {
    setDetails((d) => ({ ...d, [key]: value }));
  }, []);

  // From the details step → validate, send real files as FormData, handle success/error.
  const submit = useCallback(async () => {
    if (!detailsComplete(details)) return;
    push("user", "Mijn gegevens zijn ingevuld ✅");
    const res = computeResult(answers, uploads);
    setResult(res);
    setError(null);
    setPhase("processing");

    const payload = buildIntakePayload(answers, uploads, res, details);
    const started = Date.now();
    try {
      await sendIntake(payload, uploads);
      const wait = Math.max(0, 3000 - (Date.now() - started)); // laat de verwerkingsanimatie afspelen
      const t = setTimeout(() => setPhase("done"), wait);
      timers.current.push(t);
    } catch (err) {
      console.error("[n8n webhook] versturen mislukt:", err);
      const wait = Math.max(0, 900 - (Date.now() - started));
      const t = setTimeout(() => {
        setError("Er ging iets mis bij het versturen. Probeer het opnieuw of neem telefonisch contact op.");
        setPhase("error");
      }, wait);
      timers.current.push(t);
    }
  }, [answers, uploads, details]);

  // Na een mislukte verzending: terug naar de gegevensstap zodat men opnieuw kan versturen (data blijft behouden).
  const retry = useCallback(() => {
    setError(null);
    setPhase("details");
  }, []);

  const reset = useCallback(() => {
    timers.current.forEach(clearTimeout);
    setPhase("intro"); setStepIndex(0); setAnswers({}); setUploads({}); setDetails({});
    setResult(null); setError(null); setIsTyping(false); idRef.current = 1;
    setMessages([{ id: 0, from: "tom", text: OPENING_MESSAGE }]);
  }, []);

  const totalSteps = INTAKE_QUESTIONS.length + 2; // 7 questions + upload + details
  const currentStep =
    phase === "asking" ? stepIndex + 1 :
    phase === "upload" ? INTAKE_QUESTIONS.length + 1 :
    phase === "details" ? INTAKE_QUESTIONS.length + 2 : 0;

  return {
    phase, stepIndex, answers, uploads, details, messages, isTyping, result, error,
    totalSteps, currentStep, currentQuestion: INTAKE_QUESTIONS[stepIndex],
    start, answer, setUpload, finishPhotos, setDetail, submit, retry, reset,
  };
}

/* ============================ UI: helpers ================================ */
function Reveal({ children, delay = 0, className = "", as: Tag = "div" }) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setInView(true); io.disconnect(); } }, { threshold: 0.15 });
    io.observe(el); return () => io.disconnect();
  }, []);
  return <Tag ref={ref} className={`reveal ${inView ? "in" : ""} ${className}`} style={{ transitionDelay: `${delay}ms` }}>{children}</Tag>;
}

function useCountUp(target, active, duration = 1100) {
  const [v, setV] = useState(0);
  useEffect(() => {
    if (!active) return;
    let raf; const t0 = performance.now();
    const tick = (now) => {
      const p = Math.min(1, (now - t0) / duration);
      const eased = 0.5 - Math.cos(p * Math.PI) / 2;
      setV(Math.round(target * eased));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [target, active, duration]);
  return v;
}

function Stars({ size = 15, gap = "gap-0.5" }) {
  return <span className={`inline-flex ${gap}`}>{[...Array(5)].map((_, k) => <Star key={k} size={size} color="#f59e0b" fill="#f59e0b" />)}</span>;
}

// Image with graceful fallback so a missing/broken source never shows a broken icon.
function Photo({ src, alt, className = "", style, fallbackIcon: Fb = Snowflake }) {
  const [err, setErr] = useState(false);
  if (err || !src || src.startsWith("__ASSET")) {
    return (
      <div className={`grid place-items-center ${className}`} style={{ background: "linear-gradient(160deg,#123A63,#0A2540)", ...style }} aria-label={alt}>
        <Fb size={40} color="rgba(255,255,255,.45)" />
      </div>
    );
  }
  return <img src={src} alt={alt} loading="lazy" onError={() => setErr(true)} className={`object-cover ${className}`} style={style} />;
}

const scrollToSection = (id) => {
  const el = document.getElementById(id);
  if (el) {
    const yOffset = -80; // sticky header hoogte + marge
    const y = el.getBoundingClientRect().top + window.pageYOffset + yOffset;
    window.scrollTo({ top: y, behavior: "smooth" });
  }
};
